-- 519_batch2_curated.sql — #519 shape (a), batch 2: 59 curated rows for hidden storyless OSM pins
-- Metros: Washington, D.C., Philadelphia, Baltimore, Atlanta, Detroit, Nashville.
-- Each row: the hidden pin's EXACT name and stored coordinate (places:v34 rows, read 2026-10-22); one sentence in our own
-- words; the Wikipedia article as source_url. Candidates came from the all-metro scan (loose name match to a Wikipedia
-- article, same-article twins and wrong-type matches dropped, pins the live map already serves dropped), then each was
-- hand-judged. Every name was checked for same-name pins within 2 km (CURATED_MATCH_M): rows whose story already serves
-- through a same-name Wikipedia or storied OSM pin were cut, so no row overrides an existing story.
--
-- RUN: the SQL editor, this whole file in its own tab. Re-runnable: a row is skipped when a same-name curated row
-- already sits within 50 m. Expect 59 rows returned on the first run, 0 on a re-run.
-- THEN (new tab): select name, category, dist_m from public.curated_category_backfill(true) order by 1;
--   expect 59 rows, every dist_m 0.
-- BACK-OUT, per metro: delete from public.curated_descriptions where note = '#519 rescue line — <metro> (2026-10-22)';

with v(name, lat, lng, description, source_url, note) as (values
  ($t$Acorn$t$, 38.9895535::double precision, -77.0291232::double precision, $t$This acorn-shaped gazebo marks what is thought to be the mica-flecked spring that in 1840 led Francis Preston Blair to name his estate, and later the town, Silver Spring.$t$, $t$https://en.wikipedia.org/wiki/Acorn_Park$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Bladensburg Waterfront Park$t$, 38.9357928::double precision, -76.938426::double precision, $t$Near this riverbank on August 24, 1814, British troops routed the American defenders in the Battle of Bladensburg, opening the road to the burning of Washington.$t$, $t$https://en.wikipedia.org/wiki/Battle_of_Bladensburg$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Chevy Chase Circle$t$, 38.9676173::double precision, -77.0771458::double precision, $t$This traffic circle straddles the line between Washington and Maryland, and the fountain at its center is the Francis Griffith Newlands Memorial Fountain.$t$, $t$https://en.wikipedia.org/wiki/Chevy_Chase_Circle$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Contrabands and Freedmen Cemetery Memorial$t$, 38.7944844::double precision, -77.0497022::double precision, $t$The Union Army opened this cemetery in 1864 to bury people who had escaped slavery, and the Freedmen's Bureau ran it until it closed in 1868.$t$, $t$https://en.wikipedia.org/wiki/Contrabands_and_Freedmen_Cemetery$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Fort Ethan Allen$t$, 38.9237394::double precision, -77.1248666::double precision, $t$The Union Army threw up this earthwork in 1861 on Gilbert Vanderwerken's land as part of the ring of forts defending Washington; its remains lie inside the park.$t$, $t$https://en.wikipedia.org/wiki/Fort_Ethan_Allen_(Arlington,_Virginia)$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Fort Greble$t$, 38.8272169::double precision, -77.0145462::double precision, $t$This Civil War fort on a Congress Heights bluff guarded the meeting of the Anacostia and Potomac rivers, and is named for John Trout Greble, the first West Point graduate killed in the war.$t$, $t$https://en.wikipedia.org/wiki/Fort_Greble$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Fort Marcy Park$t$, 38.9339999::double precision, -77.1255344::double precision, $t$The remains of Fort Marcy, one of the Union forts that protected Washington during the Civil War, survive here under the National Park Service.$t$, $t$https://en.wikipedia.org/wiki/Fort_Marcy_(Virginia)$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Fort Sumner$t$, 38.9563168::double precision, -77.1220087::double precision, $t$The Union Army built Fort Sumner here in Brookmont during the Civil War, just northwest of Washington.$t$, $t$https://en.wikipedia.org/wiki/Fort_Sumner_(Maryland)$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Fort Ward - Northwest Bastion$t$, 38.8308084::double precision, -77.1025176::double precision, $t$Fort Ward was the fifth-largest of the forts built to defend Washington in the Civil War, and 90 to 95 percent of its earthen walls still stand.$t$, $t$https://en.wikipedia.org/wiki/Fort_Ward_(Virginia)$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Fort Ward Park$t$, 38.8304062::double precision, -77.1019986::double precision, $t$This park holds Fort Ward, the fifth-largest of the forts built to defend Washington in the Civil War, with 90 to 95 percent of its earthen walls still standing.$t$, $t$https://en.wikipedia.org/wiki/Fort_Ward_(Virginia)$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Frederick Douglass Home$t$, 38.8627601::double precision, -76.9850898::double precision, $t$Frederick Douglass lived in this hilltop house, which he named Cedar Hill, from 1877–78 until his death in 1895.$t$, $t$https://en.wikipedia.org/wiki/Frederick_Douglass_National_Historic_Site$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Grant Circle$t$, 38.9431164::double precision, -77.0192574::double precision, $t$This Petworth traffic circle and the houses around it form a small historic district, listed on the National Register in 2015.$t$, $t$https://en.wikipedia.org/wiki/Grant_Circle$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Huntley Mansion Park$t$, 38.7670488::double precision, -77.0916731::double precision, $t$This early-1800s Federal-style villa was the country home of Thomson Francis Mason, grandson of George Mason of Gunston Hall.$t$, $t$https://en.wikipedia.org/wiki/Huntley_(plantation)$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$John Wise's City Tavern ice well 1793$t$, 38.8057413::double precision, -77.043542::double precision, $t$This ice well belonged to John Wise's 1792 City Tavern, part of the Gadsby's Tavern complex that was a center of Alexandria's social and political life.$t$, $t$https://en.wikipedia.org/wiki/Gadsby's_Tavern$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Market Master House Historic Site$t$, 38.9387177::double precision, -76.9369334::double precision, $t$Built around 1765 when Bladensburg was a busy tobacco port, this stone house is a survivor of the town's colonial heyday.$t$, $t$https://en.wikipedia.org/wiki/Market_Master's_House_(Bladensburg,_Maryland)$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Metropolitan Branch Trail$t$, 38.9037398::double precision, -77.0043706::double precision, $t$This rail trail follows the right-of-way the Baltimore and Ohio Railroad opened in 1873 as its Metropolitan Branch, and will run eight miles from Silver Spring to Union Station when finished.$t$, $t$https://en.wikipedia.org/wiki/Metropolitan_Branch_Trail$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Oxon Run Parkway$t$, 38.8395567::double precision, -76.9811895::double precision, $t$Most of this federal parkland became Oxon Run Park in 1971; only the stretch north of 13th Street still carries the Parkway name.$t$, $t$https://en.wikipedia.org/wiki/Oxon_Run_Parkway$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Woodlawn Mansion$t$, 38.7174885::double precision, -77.1373011::double precision, $t$Once part of George Washington's Mount Vernon, Woodlawn was later split up by abolitionists to show that farming with free labor could work.$t$, $t$https://en.wikipedia.org/wiki/Woodlawn_(Fairfax_County,_Virginia)$t$, $t$#519 rescue line — Washington, D.C. (2026-10-22)$t$),
  ($t$Alexander K. McClure Elementary School$t$, 40.0150241::double precision, -75.1376347::double precision, $t$This Colonial Revival school, designed by Henry deCourcy Richards, was built in 1910–1911 and still teaches Hunting Park's children.$t$, $t$https://en.wikipedia.org/wiki/Alexander_K._McClure_School$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Alternative Middle Years at James Martin School$t$, 39.9855308::double precision, -75.097268::double precision, $t$This Fishtown middle school building is on the National Register of Historic Places, listed in 1988.$t$, $t$https://en.wikipedia.org/wiki/Alternative_Middle_Years_at_James_Martin_School$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Battleship New Jersey Museum$t$, 39.9401037::double precision, -75.1319575::double precision, $t$Moored here is USS New Jersey, the most decorated battleship ever to serve in the U.S. Navy and one of the largest ever built.$t$, $t$https://en.wikipedia.org/wiki/Battleship_New_Jersey_Museum_and_Memorial$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Burholme Park$t$, 40.0685771::double precision, -75.0920019::double precision, $t$Robert W. Ryerss left his estate to his housekeeper-turned-wife on condition that it pass to the people after her death, which is how this park and the Ryerss Museum came to the city.$t$, $t$https://en.wikipedia.org/wiki/Burholme_Park$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Caleb Pusey Historic Site$t$, 39.850668::double precision, -75.3896369::double precision, $t$The Caleb Pusey House, built in 1683, is the oldest English-built house in Pennsylvania and the only surviving house William Penn is known to have visited.$t$, $t$https://en.wikipedia.org/wiki/Caleb_Pusey_House$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Cedar Grove$t$, 39.979179::double precision, -75.2044243::double precision, $t$This house first stood in Frankford; built as a country retreat for five generations of one family, it was later moved to Fairmount Park.$t$, $t$https://en.wikipedia.org/wiki/Cedar_Grove_Mansion$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Centennial Loop$t$, 39.9800394::double precision, -75.2075399::double precision, $t$This loop runs through the grounds of the 1876 Centennial Exposition, the first official world's fair held in the United States.$t$, $t$https://en.wikipedia.org/wiki/Centennial_Exposition$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Fairmount Water Works Interpretive Center$t$, 39.9661894::double precision, -75.1835253::double precision, $t$Designed in 1812 by Frederick Graff, the Fairmount Water Works pumped the city's water until 1909 and drew tourists for its design; it is now a National Historic Landmark.$t$, $t$https://en.wikipedia.org/wiki/Fairmount_Water_Works$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Grange$t$, 39.9767905::double precision, -75.2847648::double precision, $t$The Grange Estate, a mansion also known as Maen-Coch and Clifton Hall, was built by Henry Lewis Jr., who lived from 1671 to 1730.$t$, $t$https://en.wikipedia.org/wiki/Grange_Estate$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$John M. Patterson School$t$, 39.9161874::double precision, -75.2366755::double precision, $t$This Penrose elementary school building was added to the National Register of Historic Places in 1988.$t$, $t$https://en.wikipedia.org/wiki/John_M._Patterson_School$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Major General George Gordon Meade$t$, 39.9810698::double precision, -75.2081545::double precision, $t$Alexander Milne Calder's equestrian statue of the Union general, who later served as a park commissioner, was unveiled here in 1887.$t$, $t$https://en.wikipedia.org/wiki/Equestrian_statue_of_George_Meade_(Philadelphia)$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Matthias Baldwin Park$t$, 39.9615929::double precision, -75.1689885::double precision, $t$This two-acre park was dedicated in 1991 as Franklin Town Park, part of a 1970s plan to build a city-within-a-city on cleared blocks north of Center City.$t$, $t$https://en.wikipedia.org/wiki/Matthias_Baldwin_Park$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Rocky Statue$t$, 39.9651388::double precision, -75.1792964::double precision, $t$The statue stands near the 72 museum steps that Rocky Balboa ran up in the 1976 film Rocky, one of the best-known scenes in modern cinema.$t$, $t$https://en.wikipedia.org/wiki/Rocky_Steps$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Ryerss Museum & Library$t$, 40.0686069::double precision, -75.0886742::double precision, $t$The Ryerss Mansion, also called the Burholme Mansion, was left to the city by the Ryerss family and is on the National Register of Historic Places.$t$, $t$https://en.wikipedia.org/wiki/Ryerss_Mansion$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Tacony–Palmyra Bridge Walkway$t$, 40.0080011::double precision, -75.0398074::double precision, $t$Ralph Modjeski's arch-and-drawbridge across the Delaware opened on August 14, 1929, replacing the ferry that had carried people between Tacony and Palmyra.$t$, $t$https://en.wikipedia.org/wiki/Tacony%E2%80%93Palmyra_Bridge$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$The Library Company$t$, 39.9478867::double precision, -75.1631682::double precision, $t$Benjamin Franklin founded the Library Company in 1731, and it now holds one of the most important collections of historic manuscripts and printed works in the country.$t$, $t$https://en.wikipedia.org/wiki/Library_Company_of_Philadelphia$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$The Museum of the Miraculous Medal Shrine$t$, 40.0419539::double precision, -75.1676812::double precision, $t$The shrine's church was finished in 1879 as a seminary chapel; Mary's Central Shrine was added inside it in 1927 to spread devotion to Our Lady of the Miraculous Medal.$t$, $t$https://en.wikipedia.org/wiki/Basilica_Shrine_of_Our_Lady_of_the_Miraculous_Medal$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Wall Park$t$, 40.078722::double precision, -75.1290635::double precision, $t$This park holds the Richard Wall House, built in 1682, which the Wall family owned for 165 years and was lived in without a break until 1979.$t$, $t$https://en.wikipedia.org/wiki/Richard_Wall_house$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Richard Wall Park$t$, 40.0792864::double precision, -75.1296985::double precision, $t$This park holds the Richard Wall House, built in 1682, which the Wall family owned for 165 years and was lived in without a break until 1979.$t$, $t$https://en.wikipedia.org/wiki/Richard_Wall_house$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Walt Whitman$t$, 39.9114672::double precision, -75.1733108::double precision, $t$Jo Davidson started his statue of Whitman for a 1925 competition and kept refining it long after, using a jointed armature so he could pose the figure's arms and legs.$t$, $t$https://en.wikipedia.org/wiki/Walt_Whitman_(Davidson)$t$, $t$#519 rescue line — Philadelphia (2026-10-22)$t$),
  ($t$Church Hospital$t$, 39.2930281::double precision, -76.5941668::double precision, $t$Edgar Allan Poe was brought to this hospital after being found semiconscious in a street gutter, and died here in October 1849.$t$, $t$https://en.wikipedia.org/wiki/Church_Home_and_Hospital$t$, $t$#519 rescue line — Baltimore (2026-10-22)$t$),
  ($t$Evergreen Museum & Library$t$, 39.349074::double precision, -76.6208479::double precision, $t$This historic house museum and research library is run by Johns Hopkins University alongside Homewood Museum.$t$, $t$https://en.wikipedia.org/wiki/Evergreen_Museum_%26_Library$t$, $t$#519 rescue line — Baltimore (2026-10-22)$t$),
  ($t$Katyn Memorial Park$t$, 39.2831772::double precision, -76.6016104::double precision, $t$The 44-foot statue here, the tallest in Baltimore, remembers the Polish victims of the 1940 Katyn massacre; Andrzej Pitynski's work was shipped from Poland and unveiled in 2000.$t$, $t$https://en.wikipedia.org/wiki/National_Katy%C5%84_Memorial$t$, $t$#519 rescue line — Baltimore (2026-10-22)$t$),
  ($t$St. John’s Episcopal Church$t$, 39.2727114::double precision, -76.8300132::double precision, $t$Built of local granite in 1823 on land given by Caleb Dorsey, this church was designed by Norris G. Starkweather.$t$, $t$https://en.wikipedia.org/wiki/St._John's_Episcopal_Church_(Ellicott_City,_Maryland)$t$, $t$#519 rescue line — Baltimore (2026-10-22)$t$),
  ($t$Atlanta from the Ashes$t$, 33.7546515::double precision, -84.389275::double precision, $t$Dedicated in 1969, this bronze of a woman lifted from flames by a phoenix stands for Atlanta's rise after Sherman's army burned the city.$t$, $t$https://en.wikipedia.org/wiki/Atlanta_from_the_Ashes_(The_Phoenix)$t$, $t$#519 rescue line — Atlanta (2026-10-22)$t$),
  ($t$Baltimore Block$t$, 33.7682196::double precision, -84.3885561::double precision, $t$Baltimore native Jacob J. Rosenthal built these eight rowhouses in 1885, a housing type common in Baltimore but rare in Atlanta.$t$, $t$https://en.wikipedia.org/wiki/Baltimore_Block$t$, $t$#519 rescue line — Atlanta (2026-10-22)$t$),
  ($t$Ebenezer Baptist Church, Heritage Sanctuary$t$, 33.7552179::double precision, -84.3741225::double precision, $t$Martin Luther King Sr. and Martin Luther King Jr. both preached in this church, which held King Jr.'s funeral after his assassination in 1968.$t$, $t$https://en.wikipedia.org/wiki/Ebenezer_Baptist_Church$t$, $t$#519 rescue line — Atlanta (2026-10-22)$t$),
  ($t$Henry W. Grady$t$, 33.755582::double precision, -84.3912258::double precision, $t$Alexander Doyle's statue of the newspaper editor went up in 1891, two years after Grady's death, and has drawn calls for its removal over his support of white supremacy.$t$, $t$https://en.wikipedia.org/wiki/Statue_of_Henry_W._Grady$t$, $t$#519 rescue line — Atlanta (2026-10-22)$t$),
  ($t$Historic Fire Station Number 6$t$, 33.7553377::double precision, -84.3719034::double precision, $t$Built in 1894, this is Atlanta's oldest freestanding fire station, and it is now part of the Martin Luther King Jr. National Historical Park.$t$, $t$https://en.wikipedia.org/wiki/Fire_Station_No._6_(Atlanta)$t$, $t$#519 rescue line — Atlanta (2026-10-22)$t$),
  ($t$Hurt Park$t$, 33.7539951::double precision, -84.3854168::double precision, $t$When it opened in 1940, this little triangle named for streetcar developer Joel Hurt was the first public park downtown since the 1860s.$t$, $t$https://en.wikipedia.org/wiki/Hurt_Park_(Atlanta)$t$, $t$#519 rescue line — Atlanta (2026-10-22)$t$),
  ($t$J F Kennedy Park$t$, 33.7620576::double precision, -84.4119334::double precision, $t$This Vine City park, named for President John F. Kennedy, reopened in 2019 after an extensive renovation.$t$, $t$https://en.wikipedia.org/wiki/John_F._Kennedy_Park$t$, $t$#519 rescue line — Atlanta (2026-10-22)$t$),
  ($t$Kessler Campanile$t$, 33.7743044::double precision, -84.3981828::double precision, $t$Built for the 1996 Olympics, Georgia Tech's 80-foot campanile is nicknamed The Shaft, a student joke about the school's hard curriculum.$t$, $t$https://en.wikipedia.org/wiki/Kessler_Campanile$t$, $t$#519 rescue line — Atlanta (2026-10-22)$t$),
  ($t$Martin Luther King Junior National Historic Site$t$, 33.756111::double precision, -84.3796194::double precision, $t$This park takes in Martin Luther King Jr.'s boyhood home, Ebenezer Baptist Church and the tombs of King and Coretta Scott King.$t$, $t$https://en.wikipedia.org/wiki/Martin_Luther_King_Jr._National_Historical_Park$t$, $t$#519 rescue line — Atlanta (2026-10-22)$t$),
  ($t$Underground Atlanta$t$, 33.7523647::double precision, -84.3897436::double precision, $t$First opened in 1969, Underground Atlanta sits beneath the viaducts the city built over its railroad tracks to carry later car traffic.$t$, $t$https://en.wikipedia.org/wiki/Underground_Atlanta$t$, $t$#519 rescue line — Atlanta (2026-10-22)$t$),
  ($t$Walton Spring Park$t$, 33.7596165::double precision, -84.3895648::double precision, $t$This park recalls Walton Spring, a noted resort in early Atlanta; Spring Street was named for the spring and Walton Street for its owner, early city councilman Anderson W. Walton.$t$, $t$https://en.wikipedia.org/wiki/Walton_Spring$t$, $t$#519 rescue line — Atlanta (2026-10-22)$t$),
  ($t$Fernbank Forest and Recreational Center$t$, 33.7756277::double precision, -84.322379::double precision, $t$Fernbank Forest is a 65-acre stand of mature woods with white oaks and tulip poplars up to 156 feet tall, unusually old for the Piedmont and much studied by scientists.$t$, $t$https://en.wikipedia.org/wiki/Fernbank_Forest$t$, $t$#519 rescue line — Atlanta (2026-10-22)$t$),
  ($t$James Scott$t$, 42.3351576::double precision, -82.9989426::double precision, $t$James Scott left $200,000 for a fountain to honor the people of Detroit; the 1925 fountain built in his name is controversial because of the man himself.$t$, $t$https://en.wikipedia.org/wiki/James_Scott_Memorial_Fountain$t$, $t$#519 rescue line — Detroit (2026-10-22)$t$),
  ($t$Pewabic Pottery$t$, 42.3620509::double precision, -82.9817389::double precision, $t$Founded in 1903, this pottery is known for iridescent glazes found on buildings like Chicago's Shedd Aquarium, and it is a National Historic Landmark.$t$, $t$https://en.wikipedia.org/wiki/Pewabic_Pottery$t$, $t$#519 rescue line — Detroit (2026-10-22)$t$),
  ($t$Stevens T. Mason$t$, 42.3327577::double precision, -83.0494173::double precision, $t$Michigan's first governor, the youngest person ever to serve as a U.S. state governor, is buried beneath this monument in Capitol Park, site of the old state capitol.$t$, $t$https://en.wikipedia.org/wiki/Statue_of_Stevens_T._Mason$t$, $t$#519 rescue line — Detroit (2026-10-22)$t$),
  ($t$Cheekwood Mansion$t$, 36.089208::double precision, -86.876595::double precision, $t$The Cheek family's 30,000-square-foot Georgian-style mansion opened as a botanical garden and art museum in 1960.$t$, $t$https://en.wikipedia.org/wiki/Cheekwood_Botanical_Garden_and_Museum_of_Art$t$, $t$#519 rescue line — Nashville (2026-10-22)$t$),
  ($t$Radnor Lake Natural Area and Wildlife Refuge$t$, 36.0597822::double precision, -86.8013885::double precision, $t$This 1,368-acre preserve keeps a lake and wooded hills inside Nashville, home to river otters, beavers, bald eagles and bobcats.$t$, $t$https://en.wikipedia.org/wiki/Radnor_Lake_State_Natural_Area$t$, $t$#519 rescue line — Nashville (2026-10-22)$t$)
)
insert into public.curated_descriptions (name, lat, lng, description, source_url, note)
select v.name, v.lat, v.lng, v.description, v.source_url, v.note
from v
where not exists (
  select 1 from public.curated_descriptions d
  where d.name_clean = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
    and 6371000 * sqrt(
          power(radians(d.lat - v.lat), 2) +
          power(cos(radians((d.lat + v.lat) / 2)) * radians(d.lng - v.lng), 2)) <= 50
)
returning name, note;
